async def act(page):
    import asyncio

    # The document accessible name from the accessibility tree
    doc_name = "Ludlow Seersucker Top / Manage Products / Catalog / Magento Admin"

    # Step 1: Open the Prices section in the Product Information navigation
    # Use the full path from the document node to be unambiguous
    doc = page.get_by_role("document", name=doc_name)
    await doc.get_by_role("link", name="Prices").click()

    # Give the UI a moment to reveal the Prices fields
    await asyncio.sleep(1)

    # Step 2: Locate the price input. Magento sometimes exposes the numeric price as a spinbutton,
    # sometimes as a textbox. Try both roles, then fall back to a label-based locator.
    price_locator = None
    current_value = None

    # Try spinbutton first (common for numeric inputs)
    try:
        loc = page.get_by_role("spinbutton", name="Price")
        # Attempt to read its value; if not present this will raise
        current_value = await loc.input_value()
        price_locator = loc
    except Exception:
        pass

    # If not found, try textbox
    if price_locator is None:
        try:
            loc = page.get_by_role("textbox", name="Price")
            current_value = await loc.input_value()
            price_locator = loc
        except Exception:
            pass

    # Fallback: try label-based locator (covers cases where role differs)
    if price_locator is None:
        try:
            loc = page.get_by_label("Price")
            current_value = await loc.input_value()
            price_locator = loc
        except Exception:
            pass

    if price_locator is None:
        raise RuntimeError("Unable to locate the Price input on the Prices panel.")

    # Step 3: Compute a 10% increase and update the field
    # Normalize the current value to a plain float (strip commas and currency symbols)
    raw = (current_value or "").strip()
    # Remove common currency characters and spaces
    cleaned = raw.replace(',', '').replace('$', '').replace('€', '').replace('£', '').strip()
    try:
        cur_float = float(cleaned)
    except Exception as e:
        raise RuntimeError(f"Could not parse current price value: '{current_value}'")

    new_price = round(cur_float * 1.10, 2)
    # Use two-decimal formatting
    new_price_str = f"{new_price:.2f}"

    # Fill the new value
    await price_locator.fill(new_price_str)

    # Step 4: Save the product. Use full document->button path as instructed.
    # Clicking Save usually navigates away, so make it the last action.
    await doc.get_by_role("button", name="Save").click()

